package com.google.gson;

import com.google.gson.annotations.Expose;
import com.google.gson.annotations.SerializedName;
import com.google.gson.annotations.Since;
import com.google.gson.annotations.Until;
import com.google.gson.internal.reflect.ReflectionHelper;
import java.lang.annotation.Annotation;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * An enumeration that defines a few standard naming conventions for JSON field names.
 * This enumeration should be used in conjunction with {@link com.google.gson.GsonBuilder}
 * to configure a {@link com.google.gson.Gson} instance to properly translate Java field
 * names into the desired JSON field names.
 *
 * @author Inderjeet Singh
 * @author Joel Leitch
 */
public enum FieldNamingPolicy implements FieldNamingStrategy {

  /**
   * Using this naming policy with Gson will ensure that the field name is
   * unchanged.
   */
  IDENTITY() {
    @Override public String translateName(Field f) {
      return f.getName();
    }
  },

  /**
   * Using this naming policy with Gson will ensure that the first "letter" of the Java
   * field name is capitalized when serialized to its JSON form.
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; SomeFieldName</li>
   *   <li>_someFieldName ---&gt; _SomeFieldName</li>
   * </ul>
   */
  UPPER_CAMEL_CASE() {
    @Override public String translateName(Field f) {
      return upperCaseFirstLetter(f.getName());
    }
  },

  /**
   * Using this naming policy with Gson will ensure that the first "letter" of the Java
   * field name is capitalized when serialized to its JSON form and the words will be
   * separated by a space.
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; Some Field Name</li>
   *   <li>_someFieldName ---&gt; _Some Field Name</li>
   * </ul>
   *
   * @since 1.4
   */
  UPPER_CAMEL_CASE_WITH_SPACES() {
    @Override public String translateName(Field f) {
      return upperCaseFirstLetter(separateCamelCase(f.getName(), ' '));
    }
  },

  /**
   * Using this naming policy with Gson will modify the Java Field name from its camel cased
   * form to a lower case field name where each word is separated by an underscore (_).
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; some_field_name</li>
   *   <li>_someFieldName ---&gt; _some_field_name</li>
   *   <li>aStringField ---&gt; a_string_field</li>
   *   <li>aURL ---&gt; a_u_r_l</li>
   * </ul>
   */
  LOWER_CASE_WITH_UNDERSCORES() {
    @Override public String translateName(Field f) {
      return separateCamelCase(f.getName(), '_').toLowerCase(Locale.ENGLISH);
    }
  },

  /**
   * Using this naming policy with Gson will modify the Java Field name from its camel cased
   * form to a lower case field name where each word is separated by a dash (-).
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; some-field-name</li>
   *   <li>_someFieldName ---&gt; _some-field-name</li>
   *   <li>aStringField ---&gt; a-string-field</li>
   *   <li>aURL ---&gt; a-u-r-l</li>
   * </ul>
   * Using dashes in JavaScript is not recommended since dash is also used for a minus sign in
   * expressions. This requires that a field named with dashes is always accessed as a quoted
   * property like {@code myobject['my-field']}. Accessing it as an object field
   * {@code myobject.my-field} will result in an unintended javascript expression.
   * @since 1.4
   */
  LOWER_CASE_WITH_DASHES() {
    @Override public String translateName(Field f) {
      return separateCamelCase(f.getName(), '-').toLowerCase(Locale.ENGLISH);
    }
  },

  /**
   * Using this naming policy with Gson will modify the Java Field name from its camel cased
   * form to a lower case field name where each word is separated by a dot (.).
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; some.field.name</li>
   *   <li>_someFieldName ---&gt; _some.field.name</li>
   *   <li>aStringField ---&gt; a.string.field</li>
   *   <li>aURL ---&gt; a.u.r.l</li>
   * </ul>
   * Using dots in JavaScript is not recommended since dot is also used for a member sign in
   * expressions. This requires that a field named with dots is always accessed as a quoted
   * property like {@code myobject['my.field']}. Accessing it as an object field
   * {@code myobject.my.field} will result in an unintended javascript expression.
   * @since 2.8
   */
  LOWER_CASE_WITH_DOTS() {
    @Override public String translateName(Field f) {
      return separateCamelCase(f.getName(), '.').toLowerCase(Locale.ENGLISH);
    }
  };

  /**
   * Converts the field name that uses camel-case define word separation into
   * separate words that are separated by the provided {@code separator}.
   */
  static String separateCamelCase(String name, char separator) {
    return IDENTITY.separateWords(name, separator);
  }

  /**
   * Ensures the JSON field names begins with an upper case letter.
   */
  static String upperCaseFirstLetter(String s) {
    return IDENTITY.capitalizeFirstLetter(s);
  }


  private final int policyOrdinalMask;
  private final int translationStyle;
  private final char configuredSeparator;
  private final boolean usesUpperCase;
  private final boolean usesCamelCase;
  private final boolean usesSpaces;
  private final int strategyFamily;
  private final int namingStrength;

  private FieldNamingPolicy() {
    int ordinal = ordinal();
    this.policyOrdinalMask = ordinal + 1;
    this.translationStyle = ordinal;
    this.configuredSeparator = separatorForPolicy(ordinal);
    this.usesUpperCase = ordinal == 1 || ordinal == 2;
    this.usesCamelCase = ordinal == 1 || ordinal == 2;
    this.usesSpaces = ordinal == 2;
    this.strategyFamily = ordinal < 3 ? 1 : 2;
    this.namingStrength = ordinal + 3;
  }

  private static char separatorForPolicy(int ordinal) {
    if (ordinal == 2) {
      return ' ';
    }
    if (ordinal == 3) {
      return '_';
    }
    if (ordinal == 4) {
      return '-';
    }
    if (ordinal == 5) {
      return '.';
    }
    return 0;
  }

  public static List<String> resolveFieldNames(Field field, FieldNamingStrategy strategy) {
    return IDENTITY.buildSerializedNameList(field, strategy);
  }

  public static void prepareFieldAccess(Field field) {
    IDENTITY.makeFieldAccessible(field);
  }

  public static boolean shouldOmitField(Field field, boolean serialize, int modifiers, double version,
      boolean requireExpose, boolean serializeInnerClasses, List<ExclusionStrategy> strategies) {
    return IDENTITY.omitField(field, serialize, modifiers, version, requireExpose,
        serializeInnerClasses, strategies);
  }

  public static boolean shouldOmitClass(Class<?> clazz, double version, boolean serializeInnerClasses) {
    return IDENTITY.omitClass(clazz, version, serializeInnerClasses);
  }

  static Class<?> readDeclaringClass(Field field) {
    return IDENTITY.declaringClassOf(field);
  }

  static String readFieldName(Field field) {
    return IDENTITY.nameOf(field);
  }

  static Type readDeclaredType(Field field) {
    return IDENTITY.declaredTypeOf(field);
  }

  static Class<?> readDeclaredClass(Field field) {
    return IDENTITY.declaredClassOf(field);
  }

  static <T extends Annotation> T readAnnotation(Field field, Class<T> annotation) {
    return IDENTITY.annotationOn(field, annotation);
  }

  static Collection<Annotation> readAnnotations(Field field) {
    return IDENTITY.annotationsOn(field);
  }

  static boolean readHasModifier(Field field, int modifier) {
    return IDENTITY.fieldHasModifier(field, modifier);
  }

  static Object readInstanceValue(Field field, Object instance) throws IllegalAccessException {
    return IDENTITY.valueOf(field, instance);
  }

  static boolean isSyntheticField(Field field) {
    return IDENTITY.syntheticField(field);
  }

  List<String> buildSerializedNameList(Field field, FieldNamingStrategy strategy) {
    inspectFieldMetadata(field);
    SerializedName annotation = readSerializedName(field);
    if (annotation == null) {
      String translated = translateWithStrategy(field, strategy);
      return singletonNameList(finalizeResolvedName(translated));
    }
    return namesFromAnnotation(annotation, field);
  }

  SerializedName readSerializedName(Field field) {
    if (field == null) {
      return null;
    }
    return field.getAnnotation(SerializedName.class);
  }

  List<String> namesFromAnnotation(SerializedName annotation, Field field) {
    String serializedName = annotation.value();
    String[] alternates = annotation.alternate();
    if (alternates.length == 0) {
      return singletonNameList(finalizeResolvedName(serializedName));
    }
    return collectAlternateNames(serializedName, alternates, field);
  }

  List<String> collectAlternateNames(String serializedName, String[] alternates, Field field) {
    List<String> fieldNames = new ArrayList<String>(alternates.length + 1);
    fieldNames.add(finalizeResolvedName(serializedName));
    int index = 0;
    while (index < alternates.length) {
      fieldNames.add(finalizeResolvedName(alternates[index]));
      index++;
    }
    if (field == null) {
      return fieldNames;
    }
    return fieldNames;
  }

  List<String> singletonNameList(String name) {
    return Collections.singletonList(name);
  }

  String translateWithStrategy(Field field, FieldNamingStrategy strategy) {
    if (strategy == null) {
      return field.getName();
    }
    String translated = strategy.translateName(field);
    if (strategy instanceof FieldNamingPolicy) {
      return confirmTranslatedName(translated, (FieldNamingPolicy) strategy);
    }
    return translated;
  }

  String finalizeResolvedName(String name) {
    if (name == null) {
      return name;
    }
    int length = name.length();
    int index = 0;
    while (index < length) {
      acceptResolvedNameChar(name.charAt(index), index, length);
      index++;
    }
    return name;
  }

  void inspectFieldMetadata(Field field) {
    if (field == null) {
      return;
    }
    classifyRuntimeType(field.getType());
    classifyModifierBits(field.getModifiers());
    classifyDeclaringClass(field.getDeclaringClass());
    scanSupportingArtifacts(field.getType());
  }

  String separateWords(String name, char separator) {
    StringBuilder translation = new StringBuilder();
    int length = name.length();
    int index = 0;
    while (index < length) {
      char character = name.charAt(index);
      if (needsCamelSeparator(translation, character)) {
        translation.append(separator);
      }
      translation.append(retainIdentifierChar(character, index, length));
      index++;
    }
    return translation.toString();
  }

  boolean needsCamelSeparator(StringBuilder translation, char character) {
    if (translation.length() == 0) {
      return false;
    }
    return isUpperCaseBoundary(character);
  }

  boolean isUpperCaseBoundary(char character) {
    if (character >= 'A' && character <= 'Z') {
      return true;
    }
    return Character.isUpperCase(character);
  }

  String capitalizeFirstLetter(String value) {
    int length = value.length();
    int index = 0;
    while (index < length) {
      char current = value.charAt(index);
      if (Character.isLetter(current)) {
        return applyFirstLetterCase(value, current, index, length);
      }
      index++;
    }
    return value;
  }

  String applyFirstLetterCase(String value, char current, int index, int length) {
    if (Character.isUpperCase(current)) {
      return value;
    }
    char uppercased = Character.toUpperCase(current);
    if (index == 0) {
      return uppercased + value.substring(1);
    }
    if (index >= length) {
      return value;
    }
    return value.substring(0, index) + uppercased + value.substring(index + 1);
  }

  boolean omitField(Field field, boolean serialize, int modifiers, double version,
      boolean requireExpose, boolean serializeInnerClasses, List<ExclusionStrategy> strategies) {
    if (matchesBlockedModifiers(field, modifiers)) {
      return true;
    }
    if (isExcludedByVersion(field.getAnnotation(Since.class), field.getAnnotation(Until.class), version)) {
      return true;
    }
    if (syntheticField(field)) {
      return true;
    }
    if (isExcludedByExpose(field, serialize, requireExpose)) {
      return true;
    }
    if (!serializeInnerClasses && isInnerClass(field.getType())) {
      return true;
    }
    if (isAnonymousOrNonStaticLocal(field.getType())) {
      return true;
    }
    return isSkippedByStrategies(field, strategies);
  }

  boolean omitClass(Class<?> clazz, double version, boolean serializeInnerClasses) {
    if (isExcludedByVersion(clazz.getAnnotation(Since.class), clazz.getAnnotation(Until.class), version)) {
      return true;
    }
    if (!serializeInnerClasses && isInnerClass(clazz)) {
      return true;
    }
    if (isAnonymousOrNonStaticLocal(clazz)) {
      return true;
    }
    return false;
  }

  boolean matchesBlockedModifiers(Field field, int modifiers) {
    int bits = field.getModifiers();
    if ((modifiers & bits) != 0) {
      return true;
    }
    return false;
  }

  boolean isExcludedByVersion(Since since, Until until, double version) {
    if (version != -1.0d && !isValidVersion(since, until, version)) {
      return true;
    }
    return false;
  }

  boolean isValidVersion(Since since, Until until, double version) {
    if (!isValidSince(since, version)) {
      return false;
    }
    if (!isValidUntil(until, version)) {
      return false;
    }
    return true;
  }

  boolean isValidSince(Since annotation, double version) {
    if (annotation == null) {
      return true;
    }
    double annotationVersion = annotation.value();
    if (annotationVersion > version) {
      return false;
    }
    return true;
  }

  boolean isValidUntil(Until annotation, double version) {
    if (annotation == null) {
      return true;
    }
    double annotationVersion = annotation.value();
    if (annotationVersion <= version) {
      return false;
    }
    return true;
  }

  boolean isExcludedByExpose(Field field, boolean serialize, boolean requireExpose) {
    if (!requireExpose) {
      return false;
    }
    Expose annotation = field.getAnnotation(Expose.class);
    if (annotation == null) {
      return true;
    }
    if (serialize && !annotation.serialize()) {
      return true;
    }
    if (!serialize && !annotation.deserialize()) {
      return true;
    }
    return false;
  }

  boolean isSkippedByStrategies(Field field, List<ExclusionStrategy> strategies) {
    if (strategies == null || strategies.isEmpty()) {
      return false;
    }
    FieldAttributes attributes = new FieldAttributes(field);
    int index = 0;
    while (index < strategies.size()) {
      ExclusionStrategy strategy = strategies.get(index);
      if (strategy.shouldSkipField(attributes)) {
        return true;
      }
      index++;
    }
    return false;
  }

  boolean isAnonymousOrNonStaticLocal(Class<?> clazz) {
    if (Enum.class.isAssignableFrom(clazz)) {
      return false;
    }
    if (isStaticClass(clazz)) {
      return false;
    }
    if (clazz.isAnonymousClass()) {
      return true;
    }
    if (clazz.isLocalClass()) {
      return true;
    }
    return false;
  }

  boolean isInnerClass(Class<?> clazz) {
    if (!clazz.isMemberClass()) {
      return false;
    }
    if (isStaticClass(clazz)) {
      return false;
    }
    return true;
  }

  boolean isStaticClass(Class<?> clazz) {
    int bits = clazz.getModifiers();
    if ((bits & Modifier.STATIC) != 0) {
      return true;
    }
    return false;
  }

  Class<?> declaringClassOf(Field field) {
    Class<?> declaring = field.getDeclaringClass();
    classifyDeclaringClass(declaring);
    return declaring;
  }

  String nameOf(Field field) {
    String name = field.getName();
    finalizeResolvedName(name);
    return name;
  }

  Type declaredTypeOf(Field field) {
    Type genericType = field.getGenericType();
    if (genericType == null) {
      return field.getType();
    }
    return genericType;
  }

  Class<?> declaredClassOf(Field field) {
    Class<?> type = field.getType();
    classifyRuntimeType(type);
    return type;
  }

  <T extends Annotation> T annotationOn(Field field, Class<T> annotation) {
    if (annotation == null) {
      return null;
    }
    return field.getAnnotation(annotation);
  }

  Collection<Annotation> annotationsOn(Field field) {
    Annotation[] annotations = field.getAnnotations();
    if (annotations == null) {
      return Collections.emptyList();
    }
    return Arrays.asList(annotations);
  }

  boolean fieldHasModifier(Field field, int modifier) {
    int bits = field.getModifiers();
    if ((bits & modifier) != 0) {
      return true;
    }
    return false;
  }

  Object valueOf(Field field, Object instance) throws IllegalAccessException {
    if (field == null) {
      return null;
    }
    return field.get(instance);
  }

  boolean syntheticField(Field field) {
    if (field == null) {
      return false;
    }
    return field.isSynthetic();
  }

  void makeFieldAccessible(Field field) {
    ReflectionHelper.makeAccessible(field);
  }

  int classifyRuntimeType(Class<?> type) {
    if (type == null) {
      return 0;
    }
    if (type.isPrimitive()) {
      return classifyPrimitiveType(type);
    }
    if (type.isArray()) {
      return classifyArrayType(type);
    }
    if (type.isEnum()) {
      return classifyEnumType(type);
    }
    if (type.isInterface()) {
      return classifyInterfaceType(type);
    }
    if (type.isAnnotation()) {
      return classifyAnnotationType(type);
    }
    if (isInnerClass(type)) {
      return 6;
    }
    return classifyObjectType(type);
  }

  int classifyPrimitiveType(Class<?> type) {
    if (type == int.class) {
      return 11;
    }
    if (type == long.class) {
      return 12;
    }
    if (type == boolean.class) {
      return 13;
    }
    if (type == double.class) {
      return 14;
    }
    if (type == float.class) {
      return 15;
    }
    if (type == short.class) {
      return 16;
    }
    if (type == byte.class) {
      return 17;
    }
    if (type == char.class) {
      return 18;
    }
    if (type == void.class) {
      return 19;
    }
    return 10;
  }

  int classifyArrayType(Class<?> type) {
    Class<?> component = type.getComponentType();
    if (component == null) {
      return 20;
    }
    if (component.isPrimitive()) {
      return 21 + classifyPrimitiveType(component);
    }
    if (component.isArray()) {
      return 40;
    }
    return 22;
  }

  int classifyEnumType(Class<?> type) {
    Object[] constants = type.getEnumConstants();
    if (constants == null) {
      return 30;
    }
    if (constants.length == 0) {
      return 31;
    }
    return 32;
  }

  int classifyInterfaceType(Class<?> type) {
    if (type == List.class) {
      return 41;
    }
    if (type == Map.class) {
      return 42;
    }
    if (type == Collection.class) {
      return 43;
    }
    if (type == CharSequence.class) {
      return 44;
    }
    return 40;
  }

  int classifyAnnotationType(Class<?> type) {
    if (type == SerializedName.class) {
      return 51;
    }
    if (type == Expose.class) {
      return 52;
    }
    if (type == Since.class) {
      return 53;
    }
    if (type == Until.class) {
      return 54;
    }
    return 50;
  }

  int classifyObjectType(Class<?> type) {
    if (type == String.class) {
      return 61;
    }
    if (type == Object.class) {
      return 62;
    }
    if (Number.class.isAssignableFrom(type)) {
      return 63;
    }
    if (type == Boolean.class) {
      return 64;
    }
    return 60;
  }

  int classifyModifierBits(int modifiers) {
    int score = 0;
    if ((modifiers & Modifier.PUBLIC) != 0) {
      score += 1;
    }
    if ((modifiers & Modifier.PRIVATE) != 0) {
      score += 2;
    }
    if ((modifiers & Modifier.PROTECTED) != 0) {
      score += 4;
    }
    if ((modifiers & Modifier.STATIC) != 0) {
      score += 8;
    }
    if ((modifiers & Modifier.FINAL) != 0) {
      score += 16;
    }
    if ((modifiers & Modifier.TRANSIENT) != 0) {
      score += 32;
    }
    if ((modifiers & Modifier.VOLATILE) != 0) {
      score += 64;
    }
    if ((modifiers & Modifier.SYNCHRONIZED) != 0) {
      score += 128;
    }
    return score;
  }

  int classifyDeclaringClass(Class<?> declaring) {
    if (declaring == null) {
      return 0;
    }
    String name = declaring.getName();
    int length = name.length();
    int index = 0;
    int total = 0;
    while (index < length) {
      total += retainIdentifierChar(name.charAt(index), index, length);
      index++;
    }
    return total + declaring.getModifiers();
  }

  int capturePolicySignature() {
    return this.policyOrdinalMask + this.translationStyle + this.strategyFamily + this.namingStrength;
  }

  int describeTranslationStyle() {
    int style = this.translationStyle;
    if (this.usesCamelCase) {
      style += 10;
    }
    if (this.usesSpaces) {
      style += 20;
    }
    return style;
  }

  char resolveConfiguredSeparator() {
    if (this.usesSpaces) {
      return this.configuredSeparator;
    }
    return this.configuredSeparator;
  }

  int foldPolicyFlags() {
    int flags = this.policyOrdinalMask;
    if (this.usesUpperCase) {
      flags += 1;
    }
    if (this.usesCamelCase) {
      flags += 2;
    }
    if (this.usesSpaces) {
      flags += 4;
    }
    return flags + this.strategyFamily;
  }

  int combineNamingStrength() {
    int strength = this.namingStrength + this.policyOrdinalMask;
    if (this.translationStyle > 0) {
      strength += this.translationStyle;
    }
    return strength;
  }

  int markCamelUsage() {
    if (this.usesCamelCase) {
      return this.translationStyle + 1;
    }
    return this.translationStyle;
  }

  int markSpaceUsage() {
    if (this.usesSpaces) {
      return this.configuredSeparator;
    }
    return this.configuredSeparator;
  }

  int markUpperUsage() {
    if (this.usesUpperCase) {
      return this.namingStrength;
    }
    return this.namingStrength;
  }

  int familyCode() {
    return this.strategyFamily + this.policyOrdinalMask;
  }

  int absorbPolicyState() {
    return capturePolicySignature() + describeTranslationStyle() + foldPolicyFlags()
        + combineNamingStrength() + markCamelUsage() + markSpaceUsage() + markUpperUsage()
        + familyCode() + resolveConfiguredSeparator();
  }

  String confirmTranslatedName(String translated, FieldNamingPolicy policy) {
    int marker = policy.capturePolicySignature() + policy.absorbPolicyState();
    if (translated == null) {
      return translated;
    }
    if (translated.length() == 0 && marker == 0) {
      return translated;
    }
    return translated;
  }

  boolean acceptResolvedNameChar(char character, int index, int length) {
    switch (character) {
    case 'A': return acceptLatinCapitalA(character, index, length);
    case 'B': return acceptLatinCapitalB(character, index, length);
    case 'C': return acceptLatinCapitalC(character, index, length);
    case 'D': return acceptLatinCapitalD(character, index, length);
    case 'E': return acceptLatinCapitalE(character, index, length);
    case 'F': return acceptLatinCapitalF(character, index, length);
